# Generated by Claude Opus 5.5 (claude.ai/code) · 2026-11-18
# Pester tests: report mail (swaks), its outcome recorded on the run, never silent.

BeforeAll {
    . (Join-Path $PSScriptRoot '../TestHelpers.ps1')

    function New-Notify {
        # a notify block using the swaks stub, with a password file in $Dir
        param([string]$Dir, [bool]$Enabled = $true)
        New-Item -ItemType Directory -Force -Path $Dir | Out-Null
        Set-Content -LiteralPath (Join-Path $Dir 'smtp.pass') -Value 'not-a-real-password'
        [pscustomobject]@{ enabled = $Enabled; from = 'backups@example.com'; to = @('ops@example.com', 'admin@example.com')
            server = 'smtp.example.com:587'; authUser = 'smtp-user'; passwordFile = 'smtp.pass'; swaks = $script:swaksStub }
    }
}

AfterAll {
    $env:SWAKS_STUB_FAIL = $null; $env:SWAKS_STUB_LOG = $null
    Remove-TestWork
}

Describe 'Send-BackupReport' -Skip:($IsWindows) {
    BeforeEach {
        $script:dir = Join-Path $Work ("nt-" + [guid]::NewGuid().ToString('n').Substring(0, 8))
        $script:log = Join-Path $dir 'swaks.log'
        $env:SWAKS_STUB_LOG = $log; $env:SWAKS_STUB_FAIL = $null
    }

    It 'sends nothing when notify is disabled, unless forced' {
        $n = New-Notify $dir -Enabled $false
        $r = Send-BackupReport -Notify $n -Subject 's' -Body 'b' -BaseDir $dir
        $r.Sent | Should -BeFalse
        $r.Error | Should -BeNullOrEmpty
        (Test-Path $log) | Should -BeFalse
        (Send-BackupReport -Notify $n -Subject 's' -Body 'b' -BaseDir $dir -Force).Sent | Should -BeTrue
    }

    It 'sends to every recipient' {
        $r = Send-BackupReport -Notify (New-Notify $dir) -Subject 'backup report r1' -Body 'the body' -BaseDir $dir
        $r.Sent | Should -BeTrue
        $text = Get-Content -LiteralPath $log -Raw
        $text | Should -Match '(?m)^ops@example\.com$'
        $text | Should -Match '(?m)^admin@example\.com$'
        $text | Should -Match '(?m)^Subject: backup report r1$'
        $text | Should -Match 'the body'
    }

    It 'reports a refused send with swaks'' reason, not the password' {
        $env:SWAKS_STUB_FAIL = '1'
        $r = Send-BackupReport -Notify (New-Notify $dir) -Subject 's' -Body 'b' -BaseDir $dir
        $r.Sent | Should -BeFalse
        $r.Error | Should -Match '^to ops@example\.com: swaks exit 28: <\*\* 535 5\.7\.8 Authentication failed / -> QUIT'
        $r.Error | Should -Not -Match 'not-a-real-password'
    }

    It 'reports a missing password file and a missing swaks' {
        $n = New-Notify $dir
        $n.passwordFile = 'nope.pass'
        (Send-BackupReport -Notify $n -Subject 's' -Body 'b' -BaseDir $dir).Error | Should -Match '^SMTP password file not found: '
        $n = New-Notify $dir
        $n.swaks = '/nonexistent/swaks'
        (Send-BackupReport -Notify $n -Subject 's' -Body 'b' -BaseDir $dir).Error | Should -Be 'swaks not found (/nonexistent/swaks)'
    }
}

Describe 'report mail after a run' -Skip:($IsWindows) {
    BeforeEach {
        $t = New-SpoolTestEnv -Prefix 'nr'
        $script:paths = $t.Paths
        $script:dir = Join-Path $Work ("nr-" + $t.N)
        $env:SWAKS_STUB_LOG = Join-Path $dir 'swaks.log'; $env:SWAKS_STUB_FAIL = $null
        $script:cfg = '{ "window": { "open": "00:00", "close": "23:59" }, "services": { "app": { "enabled": true, "script": "fixtures/mock-service.ps1", "steps": [ { "name": "dump" } ] } } }' | ConvertFrom-Json
        $cfg | Add-Member -NotePropertyName notify -NotePropertyValue (New-Notify $dir)
    }

    It 'records a sent report and prints a [notify] line' {
        Reset-RunOutput
        $runId = Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue
        $out = Send-RunReport -Config $cfg -Paths $paths -RunId $runId -BaseDir $dir -InformationAction Continue 6>&1
        $ev = @(Get-BackupEvents -EventsPath $paths.EventsPath | Where-Object { $_.type -eq 'notify.send' })
        $ev.Count | Should -Be 1
        $ev[0].status | Should -Be 'ok'
        $ev[0].to | Should -Be 2
        ($out | ForEach-Object { [string]$_ }) -join "`n" | Should -Match '\[notify\]\s+done\s+ok\s+report mailed to 2 recipient\(s\)'
    }

    It 'records a failed report, and show and history say so' {
        $env:SWAKS_STUB_FAIL = '1'
        $runId = Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue
        Send-RunReport -Config $cfg -Paths $paths -RunId $runId -BaseDir $dir
        $ev = @(Get-BackupEvents -EventsPath $paths.EventsPath | Where-Object { $_.type -eq 'notify.send' })[0]
        $ev.status | Should -Be 'fail'
        $ev.error | Should -Match '535'
        $events = @(Get-BackupEvents -EventsPath $paths.EventsPath)
        $detail = Get-RunDetail -Events $events -Run (Get-RunStates -Events $events -LockPath $paths.LockPath)[-1]
        $text = (Format-RunDetail -Detail $detail) -join "`n"
        $text | Should -Match '(?m)^  report mail\s+FAIL$'
        $text | Should -Match '(?m)^      ! to ops@example\.com: swaks exit 28'
        Format-RunHistoryLine -Detail $detail | Should -Match 'mail:FAIL$'
    }

    It 'records nothing when notify is disabled' {
        $cfg.notify.enabled = $false
        $runId = Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue
        Send-RunReport -Config $cfg -Paths $paths -RunId $runId -BaseDir $dir
        @(Get-BackupEvents -EventsPath $paths.EventsPath | Where-Object { $_.type -eq 'notify.send' }).Count | Should -Be 0
    }
}
